];
import { counts, fixedDue, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { settingOn, useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { hundredths, money, rateFor, sumDues, useRates } from './useRates';

/** Each person's due-total, by person id: the sum of the figures of their claims that count (open (OPEN or PENDING)
 *  claims dated within one of their holds left out unless a statement binds them; a settled claim's frozen due, else the figure their last statement
 *  bound it to, else its live due, with its late charge while overdue),
 *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
 *  then and no counting claim of theirs keeps a fixed figure or has a due (at the grade it was claimed under).
 *  A due-total is at most the sheet's cap in force on its today ('n/a' is not capped). */
export function useDueTotals(sheetId: string): Map<number, string> {
  const totals = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) totals.set(id, f.total);
  return totals;
}

/** Each person's excess, by person id: how far the sum of their figures is above the sheet's cap; 0.00 when
 *  it is not (or there is no cap, or their due-total is 'n/a'). */
export function useExcess(sheetId: string): Map<number, string> {
  const excess = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) excess.set(id, f.excess);
  return excess;
}

/** Each person's settled-total and open-total, by person id: the sum of the figures of their counting SETTLED
 *  claims, and of their counting open (OPEN or PENDING) claims, as in their due-total ('n/a' figures skipped).
 *  The two add up to the due-total before the cap. */
export function useSettledOpenTotals(sheetId: string): Map<number, { settled: string; open: string }> {
  const split = new Map<number, { settled: string; open: string }>();
  for (const [id, f] of useDueFigures(sheetId)) split.set(id, { settled: f.settled, open: f.open });
  return split;
}

/** Each person's due-total held to the cap, their excess over it, and its settled and open parts. */
function useDueFigures(sheetId: string): Map<number, { total: string; excess: string; settled: string; open: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const settings = useSettings(sheetId).data;
  const holds = holdsById(people.data, today.data?.today);
  const cap = settingOn(settings, 'cap', today.data?.today);
  const totals = new Map<number, { total: string; excess: string; settled: string; open: string }>();
  for (const p of people.data ?? []) {
    const counting = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c, holds, today.data?.today));
    const rated = rateFor(rates.data, p.grade, today.data?.today) !== undefined;
    const dues = counting.map((c) =>
      claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings, today.data?.today, gradeOn(p, c.date)));
    const shown = rated || counting.some((c) => fixedDue(c) !== null && fixedDue(c) !== 'n/a') || dues.some((d) => d !== 'n/a');
    const sum = sumDues(dues);
    const over = shown && cap !== null && hundredths(sum) > hundredths(cap);
    totals.set(p.id, {
      total: !shown ? 'n/a' : over ? cap : sum,
      excess: over ? money(hundredths(sum) - hundredths(cap)) : '0.00',
      settled: sumDues(dues.filter((_, i) => counting[i].status === 'SETTLED')),
      open: sumDues(dues.filter((_, i) => counting[i].status !== 'SETTLED')),
    });
  }
  return totals;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-mm-dd; null when it
 *  applies from the beginning of time) through its to-date (null when it has no end). */
export type Rate = { grade: string; pct: string; from: string | null; to: string | null };

export function ratesKey(sheetId: string) {
  return ['sheet', sheetId, 'rates'];
}

/** The sheet's rates, by grade then from-date (an undated rate first); a grade with no rate is not
 *  listed. */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: async () =>
      (await getJson<{ rates: Rate[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`)).rates,
  });
}

/** The rate (a two-decimal percent) for a grade in force on a date (yyyy-mm-dd): the one with the
 *  latest from-date on or before it, an undated rate applying from the beginning of time; undefined
 *  when none applies, or the date is after that rate's to-date. */
export function rateFor(rates: Rate[] | undefined, grade: string | undefined, on: string | undefined): string | undefined {
  if (on === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > on)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  if (found?.to != null && found.to < on) return undefined;
  return found?.pct;
}

/** A two-decimal number as a whole count of hundredths ("12.50" -> 1250, "-0.30" -> -30). */
export function hundredths(v: string): bigint {
  const t = v.trim();
  const negative = t.startsWith('-');
  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

/** A whole count of hundredths as a two-decimal number (-30 -> "-0.30"). */
export function money(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/** A rate figure: an amount (two decimals) times a rate (a two-decimal percent), divided by 100, rounded
 *  half up (when `halfUp`) or half to even to two decimals — not floored (see `atLeast`); 'n/a' when there is
 *  no rate. Worked in whole numbers, so exact. */
export function due(amount: string, pct: string | undefined, halfUp: boolean): string {
  if (pct === undefined) return 'n/a';
  return money(percentOf(amount, pct, 1n, halfUp));
}

/** A figure (two decimals) raised to at least a floor (two decimals; none when undefined); 'n/a' stays 'n/a'. */
export function atLeast(figure: string, floor: string | undefined): string {
  if (figure === 'n/a' || floor === undefined || hundredths(figure) >= hundredths(floor)) return figure;
  return money(hundredths(floor));
}

/** Whether an amount (two decimals) is a correction's: below zero. */
export function isCorrection(amount: string): boolean {
  return hundredths(amount) < 0n;
}

/** An amount (two decimals) times a rate (a two-decimal percent) times a whole number, divided by
 *  100, rounded half up (when `halfUp`, away from zero) or half to even, in hundredths (a negative amount rounds as its size does, then takes
 *  its sign back). */
function percentOf(amount: string, pct: string, times: bigint, halfUp: boolean): bigint {
  const signed = hundredths(amount) * hundredths(pct) * times; // in 1/1_000_000 of a unit
  const product = signed < 0n ? -signed : signed;
  const rest = product % 10000n;
  let cents = product / 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return signed < 0n ? -cents : cents;
}

/** A figure (two decimals) with a late charge added on top: for each full 30 days, the late percent
 *  (two decimals) in force on that boundary of the figure plus the charges of the boundaries before it (compounding), each rounded like a due, the charges added up;
 *  'n/a' stays 'n/a'. */
export function withCharge(figure: string, latePcts: string[], halfUp: boolean): string {
  if (figure === 'n/a') return figure;
  return money(latePcts.reduce((sum, pct) => sum + percentOf(money(sum), pct, 1n, halfUp), hundredths(figure)));
}

/** Dues added up, skipping 'n/a'. */
export function sumDues(dues: string[]): string {
  return money(dues.filter((d) => d !== 'n/a').reduce((sum, d) => sum + hundredths(d), 0n));
}

/** A sheet's total of people's figures: added up, skipping 'n/a', but leaving out the single highest
 *  and the single lowest figure when three or more people have one. */
export function trimmedSum(figures: string[]): string {
  const cents = figures.filter((d) => d !== 'n/a').map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = cents.length >= 3 ? cents.slice(1, -1) : cents;
  return money(kept.reduce((sum, c) => sum + c, 0n));
}

